DROP TABLE IF EXISTS `view_cotizaciones`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `view_cotizaciones`  AS SELECT `c`.`cotizacion_id` AS `cotizacion_id`, `c`.`numero` AS `numero`, `c`.`fecha` AS `fecha`, `cl`.`documento` AS `documento`, `cl`.`datos` AS `cliente_nombre`, `c`.`total` AS `total`, `c`.`total`/ 1.18 AS `subtotal`, `c`.`total`/ 1.18 * 0.18 AS `igv`, `u`.`nombres` AS `vendedor`, `c`.`estado` AS `estado`, `c`.`id_usuario` AS `id_usuario`, `c`.`sucursal` AS `sucursal`, `c`.`moneda` AS `moneda`, `c`.`cm_tc` AS `cm_tc` FROM ((`cotizaciones` `c` left join `clientes` `cl` on(`c`.`id_cliente` = `cl`.`id_cliente`)) left join `usuarios` `u` on(`c`.`id_usuario` = `u`.`usuario_id`)) WHERE `c`.`estado` <> '2' ORDER BY `c`.`fecha` DESC, `c`.`numero` AS `DESCdesc` ASC  ;

