CREATE ALGORITHM=UNDEFINED DEFINER=`magusqao`@`localhost` SQL SECURITY DEFINER VIEW `view_ventas`  AS SELECT `v`.`id_venta` AS `cod_v`, concat(`ds`.`abreviatura`,' | ',`v`.`serie`,' - ',`v`.`numero`) AS `sn_v`, concat(`c`.`documento`,' | ',`c`.`datos`) AS `datos_cl`, concat(if(`v`.`moneda` = 1,'S/ ','$ '),if(`v`.`apli_igv` = '1',`v`.`total` / (`v`.`igv` + 1),`v`.`total`)) AS `subtotal`, concat(if(`v`.`moneda` = 1,'S/ ','$ '),if(`v`.`apli_igv` = '1',`v`.`total` / (`v`.`igv` + 1) * `v`.`igv`,0)) AS `igv_v`, concat(`v`.`enviado_sunat`,'-',`v`.`id_tido`,'-',`v`.`id_venta`) AS `doc_ventae`, concat(`v`.`id_venta`,'--',`vs`.`nombre_xml`) AS `id_venta`, `v`.`fecha_emision` AS `fecha_emision`, `ds`.`abreviatura` AS `abreviatura`, `v`.`apli_igv` AS `apli_igv`, `v`.`igv` AS `igv`, `v`.`id_tido` AS `id_tido`, `v`.`serie` AS `serie`, `v`.`numero` AS `numero`, `c`.`documento` AS `documento`, `c`.`datos` AS `datos`, concat(if(`v`.`moneda` = 1,'S/ ','$ '),`v`.`total`) AS `total`, `v`.`estado` AS `estado`, `v`.`enviado_sunat` AS `enviado_sunat`, `vs`.`nombre_xml` AS `nombre_xml` FROM (((`ventas` `v` left join `documentos_sunat` `ds` on(`v`.`id_tido` = `ds`.`id_tido`)) left join `clientes` `c` on(`v`.`id_cliente` = `c`.`id_cliente`)) left join `ventas_sunat` `vs` on(`v`.`id_venta` = `vs`.`id_venta`)) WHERE `v`.`id_empresa` = '12' AND `v`.`sucursal` = '1' ORDER BY `v`.`fecha_emision` ASC, `v`.`numero` ASC  ;

